import android.content.Context;import android.content.Intent;import android.graphics.Bitmap;import android.graphics.BitmapFactory;import android.media.MediaScannerConnection;import android.net.Uri;import android.os.Environment;import android.util.Base64;import android.webkit.JavascriptInterface;import android.widget.Toast;import java.io.File;import java.io.FileOutputStream;import java.io.IOException;public class WebAppInterface {private Context mContext;public WebAppInterface(Context c) {mContext = c;}@JavascriptInterface public void saveBase64Image(String base64Data, String fileName) {try {if (base64Data.contains(",")) {base64Data = base64Data.split(",")[1];}byte[] decodedBytes = Base64.decode(base64Data, Base64.DEFAULT);Bitmap bitmap = BitmapFactory.decodeByteArray(decodedBytes, 0, decodedBytes.length);File directory = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS);File file = new File(directory, fileName + ".jpg");FileOutputStream fos = new FileOutputStream(file);bitmap.compress(Bitmap.CompressFormat.JPEG, 100, fos);fos.flush();fos.close();MediaScannerConnection.scanFile(mContext, new String[]{file.getAbsolutePath()}, null, null);Toast.makeText(mContext, "Imagem salva em Downloads", Toast.LENGTH_SHORT).show();} catch (IOException e) {e.printStackTrace();Toast.makeText(mContext, "Erro ao salvar imagem", Toast.LENGTH_SHORT).show();}}@JavascriptInterface public void openExternalApp(String url) {try {Intent intent = new Intent(Intent.ACTION_VIEW, Uri.parse(url));intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);mContext.startActivity(intent);} catch (Exception e) {Toast.makeText(mContext, "Aplicativo não encontrado", Toast.LENGTH_SHORT).show();}}}